const main=document.querySelector('main');
const visit='<section class="cta"><div class="eyebrow" style="justify-content:center">There is a place for you here</div><h2>Your next Sunday<br>could be a new beginning.</h2><p>Come as you are. Join us in worship, prayer and the Word.</p><a class="button" href="#contact">Plan your visit <span>↗</span></a></section>';
const services=`<section class="section services weekly-services" id="services"><div class="section-head"><div><div class="eyebrow">Gather with us</div><h2>A rhythm of worship.<br>A lifetime of growth.</h2></div><p class="muted">A place to worship, learn and pray throughout the week.<br>All times are local to Cameroon.</p></div><div class="service-grid"><article class="service"><span class="number">01 /</span><h3>Sunday worship</h3><p>Worship with us through praise, prayer, fellowship and the teaching of God's Word.</p><strong>Sunday · 8:30 a.m.–12:30 p.m.</strong><small>A welcoming gathering for you and your family</small></article><article class="service"><span class="number">02 /</span><h3>Bible study</h3><p>Open the Scriptures with us and discover how God's Word speaks to everyday life.</p><strong>Wednesday · 6:00 p.m.</strong><small>Learn, reflect and grow together</small></article><article class="service"><span class="number">03 /</span><h3>Prayer Band</h3><p>Join us in prayer as we seek God's presence and support one another.</p><strong>Thursday · from 5:30 p.m.</strong><small>Everyone is welcome to pray with us</small></article></div></section>`;
const pageHero=(label,title,copy)=>`<section class="page-hero ${label==='About our church'?'about-page-hero':label==='Outreach'?'outreach-page-hero':label==='Our vision'?'vision-page-hero':label==='Contact & directions'?'contact-page-hero':''}"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${copy}</p></section>`;
const pages={
home:()=>`<section class="hero"><div><div class="eyebrow">Welcome to Motowoh District</div><h1>A family in Christ.<br>A place to <em>belong.</em></h1><p>Growing in faith. Grounded in the Word.<br>Join The Apostolic Church, Motowoh District, as we worship God and share the love of Jesus.</p><div class="actions"><a class="button gold" href="#contact">Come worship with us <span>↗</span></a><a class="button outline" href="#about">Discover our church <span>→</span></a></div></div><div class="hero-bottom"><a href="#contact">◷ <span>SUNDAY WORSHIP · 8:30 A.M.</span></a><a href="#gatherings">Explore our community ↓</a></div></section><section class="section intro-grid church-intro"><div class="church-intro-copy"><div class="eyebrow">Faith brings us together</div><h2>A church family.<br><em>A place for you.</em></h2><p class="intro-lead">Know Jesus. Grow in His Word.<br>Share His love.</p><p class="intro-description">Here in Motowoh Newtown, Limbe, we grow together in faith. Whether you are new to faith or looking for a church home, you are welcome at Motowoh District.</p><a class="text-link" href="#about">Get to know us &nbsp; ↗</a></div><div class="photo-block"><img src="assets/carousel.jpg" loading="lazy" alt="A gathering of the Motowoh church community"><div class="photo-tag">Together in faith. Together in love.</div></div></section>${services}<section class="section gallery" id="gatherings"><div class="gallery-intro"><div class="eyebrow">Life at Motowoh</div><h2>Our shared journey.</h2><p>Glimpses of our church family, gathered in fellowship.</p><a class="text-link facebook-link" href="https://m.facebook.com/story.php?story_fbid=pfbid0sKjMrPHEFRfrXVrJBq97Umjk1xQ41kx8LuV7rDdSR7T86Pg8nkHMEHyLiLjg8gJNl&amp;id=61595305581705" target="_blank" rel="noopener noreferrer">Sunday worship highlights on Facebook ↗</a></div><div class="carousel" aria-roledescription="carousel" aria-label="Church community photographs"><div class="gallery-frame"><img id="slide-image" src="assets/facebook-worship.jpg" loading="lazy" alt="Motowoh District church gathering, photograph 1"></div><div class="carousel-caption"><div class="gallery-progress"><span id="slide-count" aria-live="polite">01 / 06</span><div class="dots" aria-label="Choose a photograph"></div></div><div class="carousel-controls"><button class="icon-button" id="previous" aria-label="Previous photograph">←</button><button class="icon-button" id="pause" aria-label="Pause slideshow">Ⅱ</button><button class="icon-button" id="next" aria-label="Next photograph">→</button></div></div></div></section><section class="section media-section" id="church-media"><div class="section-head"><div><div class="eyebrow">Tacc Motowoh Media</div></div><p class="muted">Watch our featured video and explore more moments from the church on TikTok.</p></div><div class="media-grid"><article class="featured-video"><iframe src="https://www.tiktok.com/player/v1/7697941525740768529?autoplay=0&controls=1&description=1&rel=0" title="Featured video from Tacc Motowoh Media" loading="lazy" allow="fullscreen; encrypted-media" allowfullscreen></iframe><a class="text-link" href="https://www.tiktok.com/@tacc.motowoh.medi/video/7697941525740768529" target="_blank" rel="noopener">Watch this video on TikTok ↗</a></article><div class="media-feed"><h3>More from Motowoh</h3><iframe src="tiktok-feed.html" title="Tacc Motowoh Media TikTok profile and recent videos" loading="lazy"></iframe><p class="note">If TikTok doesn't load in your browser, use the link below to watch.</p><a class="button" href="https://www.tiktok.com/@tacc.motowoh.medi" target="_blank" rel="noopener">Explore Tacc Motowoh Media ↗</a></div></div></section>${visit}`,
about:()=>`${pageHero('About our church','Rooted in Christ.<br>Growing in faith.','The Apostolic Church, Motowoh District, is a welcoming church family in Motowoh Newtown, Limbe, Cameroon.')}<section class="section intro-grid"><div class="photo-block"><img src="assets/discrit pastor.jpg" alt="Motowoh District pastor" loading="lazy"><div class="photo-tag">Serving God. Caring for our church family.</div></div><div><div class="eyebrow">Who we are</div><h2>A faith we share.<br>A family where all belong.</h2><p class="muted">At the heart of our life together are Jesus Christ, prayer and the teaching of God's Word. We gather to worship, strengthen one another and grow as disciples of Christ.</p><p class="muted">Our district pastor guides and serves the congregation as we share the gospel and help one another grow in God's Word.</p><a class="text-link" href="#vision">Explore our vision &nbsp; ↗</a></div></section><section class="section services about-life"><div class="eyebrow">Our life together</div><h2>Faith for everyday life.</h2><div class="values"><article><h3>Worship</h3><p>We praise God together, give thanks for His goodness and listen to the teaching of His Word.</p></article><article><h3>The Word</h3><p>Scripture guides our choices, strengthens our faith and teaches us to live with love.</p></article><article><h3>Fellowship</h3><p>Through prayer, encouragement and shared life, we help one another keep growing.</p></article></div></section><section class="section heritage"><div class="intro-grid"><div><div class="eyebrow">Our Apostolic heritage</div><h2>A story that began<br>here in Limbe.</h2></div><div><p class="muted">The Apostolic Church in Cameroon traces its beginnings to Victoria, now Limbe, in 1949. Elder O. I. Oyoyo began praying with his family and gathering believers after moving from Nigeria to work at Victoria General Hospital.</p><p class="muted">Missionary D. H. Maggil visited in 1950. In 1952, Pastor O. E. Hogan became the church's first resident pastor. From these early gatherings, the church grew into communities across Cameroon.</p><a class="text-link" href="https://tacccameroon.org/our-history/" target="_blank" rel="noopener">Read the national church's history &nbsp; ↗</a></div></div><ol class="history-timeline"><li><span>1949</span><h3>Prayer gatherings begin</h3><p>Elder O. I. Oyoyo and his family gather believers in Victoria.</p></li><li><span>1952</span><h3>A pastor arrives</h3><p>Pastor O. E. Hogan begins serving as the first resident pastor.</p></li><li><span>1965</span><h3>A chapel is built</h3><p>A permanent chapel is erected during Pastor A. Ntungwen's ministry.</p></li></ol><p class="note">These milestones reflect the history of our wider church family, The Apostolic Church Cameroon.</p></section><section class="section beliefs"><div class="eyebrow">What we believe</div><h2>Jesus Christ and His Word<br>are our foundation.</h2><p class="belief-intro">Our faith is guided by the published tenets of The Apostolic Church Cameroon. Here are some of their central teachings.</p><div class="values"><article><h3>One God: Father, Son and Holy Spirit</h3><p>We believe in one God, revealed as Father, Son and Holy Spirit, and trust the divine inspiration and authority of Scripture.</p></article><article><h3>Salvation through Jesus Christ</h3><p>We believe in Jesus' birth, sinless life, saving death, resurrection and return, and in the new life God offers through Him.</p></article><article><h3>Life in the Holy Spirit</h3><p>We believe the Holy Spirit equips the church, and we practise baptism by immersion and share in the Lord's Supper.</p></article></div><a class="text-link" href="https://tacccameroon.org/wp-content/uploads/2024/01/Tenets1.pdf" target="_blank" rel="noopener">Read all eleven official tenets (PDF) &nbsp; ↗</a></section>${visit}`,
outreach:()=>`${pageHero('Outreach','Sharing Jesus.<br>Beyond our walls.','Our calling reaches beyond our gatherings: to share the good news and invite others into a life of faith.')}<section class="section intro-grid"><div><div class="eyebrow">A faith to share</div><h2>Every soul matters.<br>Every invitation counts.</h2><p class="muted">Winning souls for Christ begins with sharing His love. Our outreach vision invites every member to speak about Jesus, pray for others and welcome people into the church family.</p><p class="muted">Outreach is also about helping people grow. We seek to walk alongside those who respond to the gospel, encouraging them to be grounded in God's Word.</p><a class="button" href="#contact">Talk with us about getting involved ↗</a></div><div class="photo-block"><img src="assets/carousel3.jpg" alt="Members of the Motowoh church community" loading="lazy"></div></section><section class="section services outreach-actions"><div class="eyebrow">Live the calling</div><h2>Simple steps. Eternal purpose.</h2><div class="values"><article><h3>Pray for someone</h3><p>Bring your family, neighbours and community before God in prayer. Join our Thursday Prayer Band.</p></article><article><h3>Share the good news</h3><p>Tell someone about the hope you have in Jesus, with kindness and care.</p></article><article><h3>Invite and encourage</h3><p>Invite someone to Sunday worship and help them find fellowship and encouragement in the Word.</p></article></div></section>${visit}`,
vision:()=>`${pageHero('Our vision','Win souls.<br>Nourish faith.','To win souls for Christ and feed them with the Word of God.')}<section class="quote vision-quote"><div class="eyebrow" style="justify-content:center">Our guiding purpose</div><blockquote>“To win souls for Christ and feed them with the Word of God.”</blockquote><span>THE APOSTOLIC CHURCH · MOTOWOH DISTRICT</span></section><section class="section vision-growth"><div class="intro-grid"><div><div class="eyebrow">Reaching and nurturing</div><h2>A new beginning.<br>A growing faith.</h2></div><p class="muted">Our vision holds two things together: reaching people with the gospel of Jesus Christ, and helping them grow through the truth of Scripture. We want every gathering to encourage a faith that continues throughout the week.</p></div><div class="values"><article><h3>Reach with love</h3><p>Share the message of salvation and welcome people to know Christ.</p></article><article><h3>Root in the Word</h3><p>Teach the Bible so believers can grow in understanding and put their faith into practice.</p></article><article><h3>Grow together</h3><p>Strengthen one another through worship, fellowship and united prayer.</p></article></div></section>${services}${visit}`,
contact:()=>`${pageHero('Contact & directions','We look forward<br>to welcoming you.','Visit us in Motowoh Newtown, Limbe. Come for worship, Bible study or a time of prayer.').replace('class="page-hero"','class="page-hero contact-page-hero"')}<section class="section contact-grid"><div><div class="eyebrow">Find us</div><h2>Make yourself<br>at home.</h2><h3>The Apostolic Church<br>Motowoh District</h3><p class="muted">Motowoh Newtown<br>Limbe, Cameroon</p><div class="contact-phones"><h3>Call us</h3><a href="tel:+237670204421">(+237) 670 204 421</a><a href="tel:+237678456659">(+237) 678 456 659</a></div><a class="button" href="https://www.google.com/maps/dir/?api=1&destination=Motowoh%20Newtown%2C%20Limbe%2C%20Cameroon" target="_blank" rel="noopener">Get directions in Google Maps ↗</a><p class="note">The map shows the Motowoh Newtown area. The destination is an area search, rather than a verified church entrance.</p><p class="muted">For prayer or to learn more about the church, speak with our welcome team when you visit a gathering.</p></div><iframe class="map" title="Google Maps: Motowoh Newtown, Limbe, Cameroon" src="https://maps.google.com/maps?q=Motowoh%20Newtown%20Limbe%20Cameroon&t=&z=14&ie=UTF8&iwloc=&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></section>${services}`};
let timer;function render(){clearInterval(timer);const key=location.hash.slice(1)||'home';if(['services','gatherings'].includes(key))return;const page=pages[key]?key:'home';main.innerHTML=pages[page]();setupRevealAnimations();document.title=`${{home:'Welcome',about:'About us',outreach:'Outreach',vision:'Our vision',contact:'Contact & directions'}[page]} | The Apostolic Church · Motowoh District`;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');window.scrollTo({top:0,left:0,behavior:'instant'});if(page==='home')setupCarousel();applyLanguage()}
function setupCarousel(){const files=['facebook-worship.jpg','carousel.jpg','carousel1.jpg','carousel2.jpg','carousel3.jpg','carousel4.jpg'];let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;const dots=document.querySelector('.dots');files.forEach((_,i)=>{const b=document.createElement('button');b.className='dot';b.setAttribute('aria-label',`Show photograph ${i+1}`);b.onclick=()=>show(i);dots.append(b)});function show(i){index=(i+files.length)%files.length;const img=document.querySelector('#slide-image');img.classList.remove('photo-enter');img.onload=()=>{img.classList.remove('photo-enter');void img.offsetWidth;img.classList.add('photo-enter')};img.src='assets/'+files[index];img.alt=index===0?"Sunday worship highlight from Tacc Motowoh Media on Facebook":`Motowoh District church gathering, photograph ${index}`;document.querySelector('#slide-count').textContent=`0${index+1} / 06`;[...dots.children].forEach((b,n)=>{b.classList.toggle('selected',n===index);b.setAttribute('aria-pressed',String(n===index))});applyLanguage()}document.querySelector('#previous').onclick=()=>show(index-1);document.querySelector('#next').onclick=()=>show(index+1);const pause=document.querySelector('#pause');function pauseLabel(){pause.textContent=paused?'▷':'Ⅱ';pause.setAttribute('aria-label',paused?'Play slideshow':'Pause slideshow');applyLanguage()}pause.onclick=()=>{paused=!paused;pauseLabel()};pauseLabel();timer=setInterval(()=>{if(!paused&&!document.hidden&&!document.querySelector('.carousel').contains(document.activeElement))show(index+1)},5000);show(0)}
function closeNavigation(){document.querySelector('nav').classList.remove('open');const button=document.querySelector('.menu-toggle');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open navigation');applyLanguage()}
document.querySelector('.menu-toggle').onclick=function(){const open=document.querySelector('nav').classList.toggle('open');this.setAttribute('aria-expanded',String(open));this.setAttribute('aria-label',open?'Close navigation':'Open navigation');applyLanguage()};
document.querySelectorAll('nav a').forEach(link=>link.addEventListener('click',closeNavigation));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.querySelector('nav').classList.contains('open')){closeNavigation();document.querySelector('.menu-toggle').focus()}});
document.querySelector('#year').textContent=new Date().getFullYear();window.addEventListener('hashchange',render);render();
function setupRevealAnimations(){
 setupRevealAnimations.observer?.disconnect();
 const targets=[...document.querySelectorAll('main .church-intro-copy,main .photo-block,main .gallery-intro,main .carousel,main .featured-video,main .media-feed,main .cta>*,main .page-hero,main .quote,main .section-head,main .services>.eyebrow,main .services>h2,main .values article,main .service,main .heritage .intro-grid,main .history-timeline li,main .contact-grid>div,main .map')];
 if(!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches){targets.forEach(el=>el.classList.add('is-visible'));return}
 const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.08,rootMargin:'0px 0px -24px 0px'});
 setupRevealAnimations.observer=observer;
 targets.forEach(el=>{const siblings=[...el.parentElement.children];el.style.setProperty('--reveal-delay',Math.min(siblings.indexOf(el),3)*70+'ms');el.classList.add('reveal-ready');observer.observe(el)});
}
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>setupRevealAnimations());
